"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** 3D curvature with thick slats. Color: Dark. */
export function ShutterCurvedThickDark(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      slatSize="thick"
      curved
      defaultLevel={55}
      variant="dark"
      label="Curved thick · Dark"
      {...props}
    />
  );
}
